 for(const literal of seenOnSource)
  occurrences.set(literal,(occurrences.get(literal)??0)+1);
 for(const literal of claimed){
  const count=occurrences.get(literal)??0;
  if(count===0)return false;
  occurrences.set(literal,count-1);
 }
 return [...occurrences.values()].every(count=>count===0);
}
/**
 * Every visible word must belong to a model-captured description or unit.
 * Otherwise a trailing "IVA incluido", "pago contado", "flete sin cargo"
 * or other commercial condition could vanish without affecting the sums.
 * Allow only arithmetic "x" after subtracting source-exact fields.
 */
function unclaimedWords(source:string,line:Line):boolean{
 let left=source;
 const consume=(v:string|null):boolean=>{
  if(v===null||v.length===0)return true;
  const index=left.toLocaleLowerCase('es-AR').indexOf(
   v.toLocaleLowerCase('es-AR'));
  if(index<0)return false;
  left=left.slice(0,index)+' '+left.slice(index+v.length);
  return true;
 };
 if(!consume(line.original_description)||!consume(line.unit)||
    !consume(line.unit_price)||!consume(line.line_total))return true;
 // Numbers are already checked by remainingNumberCovered: after removing
 // descriptions and money, each is the explicitly declared quantity.
 left=left.replace(/\d+(?:[.,]\d+)?/gu,' ');
 const words=left.match(/\p{L}+/gu)??[];
 return words.some(word=>word.toLocaleLowerCase('es-AR')!=='x');
}
function remainingNumberCovered(source:string,line:Line):boolean{
 // Remove source-exact description and the full money tokens first, so
 // weights ("50 kg"), sizes ("2,5 mm²"), and prices are not mistaken for
 // a missing requested quantity.
 const lower=source.toLocaleLowerCase('es-AR');
 const needle=line.original_description.toLocaleLowerCase('es-AR');
 const start=lower.indexOf(needle);
 if(start<0)return false;
 const noDescription=source.slice(0,start)+' '+source.slice(
   start+line.original_description.length);
 const residual=noDescription.replace(DOLLARS,' ');
 const numeric=[...residual.matchAll(/(?<![\p{L}\p{N}])\d+(?:[.,]\d+)?(?![\p{L}\p{N}])/gu)]
  .map(m=>m[0]);
 if(numeric.length===0)return true;
 if(line.quantity===null)return false;
 return numeric.every(n=>n===line.quantity);
}
/** Source-level textual coverage, not supplier identity vetting. */
export function checkSupplierTextSource(
 source:DownloadedMedia,proposal:DocumentDraft
):SourceCheckResult{
 const hash=source?.sha256??null;
 if(!source||!(source.bytes instanceof Uint8Array)||
   !/^[a-f0-9]{64}$/u.test(source.sha256)||
   !proposal||proposal.kind!=='supplier_quote'||
   !Array.isArray(proposal.lines))
  return not('invalid_source',0,null);
 if(source.mime!=='text/plain'&&source.mime!=='text/csv')
  return not('unsupported_format',proposal.lines.length,hash);
 if(source.bytes.byteLength<8||source.bytes.byteLength>3*1024*1024)
  return not('invalid_source',0,hash);
 let original:string;
 try{original=new TextDecoder('utf-8',{fatal:true}).decode(source.bytes)}
 catch{return not('invalid_source',0,hash)}
 if(original.charCodeAt(0)===0xfeff)original=original.slice(1);
 if(original.length>18000||HAS_CONTROL.test(original))
  return not('invalid_source',0,hash);
 if(PII.test(original))return not('unsafe_contact',proposal.lines.length,hash);
 if(proposal.unanswered.length>0||proposal.lines.some(
  l=>l.ambiguity!==null&&l.ambiguity.trim()!==''))
  return not('unresolved',proposal.lines.length,hash);
 const lines=original.replace(/\r\n|\r/gu,'\n').split('\n')
  .map(s=>s.trim()).filter(Boolean);
 // Strict ordered product rows first, followed by exactly one TOTAL
 // and optional non-monetary notes either before or after TOTAL. Notes
 // are never turned into price lines or allowed to conceal extra charges.
 const n=proposal.lines.length;
 if(n<1||n>25||lines.length<n+1||lines.length>n+21)
  return not('unsupported_layout',n,hash);
 const tail=lines.slice(n);
 const totalIndices=tail.flatMap((row,i)=>
  /^(?:total(?:\s+(?:final|general|a\s+pagar))?|importe\s+total)\s*[:=]?/iu.test(row)?[i]:[]);
 if(totalIndices.length!==1)return not('total_not_found',n,hash);
 const total=tail[totalIndices[0]];
 const notes=tail.filter((_,i)=>i!==totalIndices[0]);
 const note=(proposal.requested_delivery_note??'').trim();
 const clauses=note.split(/[;\r\n]+/u).map(v=>v.trim()).filter(Boolean);
 if(notes.some(v=>moneyTokens(v).length>0))
  return not('uncovered_money',n,hash);
 const norm=(v:string)=>v.replace(/\s+/gu,' ').trim().toLocaleLowerCase('es-AR');
 const complete=norm(note);
 if(notes.some(v=>!complete.includes(norm(v)))||
    clauses.some(v=>!notes.some(row=>norm(row).includes(norm(v)))))
  return not('uncovered_terms',n,hash);
 const totalMatch=total.match(
  /^(?:total(?:\s+(?:final|general|a\s+pagar))?|importe\s+total)\s*[:=]?\s*/iu);
 if(!totalMatch||
    typeof proposal.total_declared!=='string'||
    !moneyTokens(total).includes(proposal.total_declared)||
    moneyTokens(total).length!==1)
  return not('total_not_found',proposal.lines.length,hash);
 // A total with extra wording ("IVA incluido", "pago a 30 días", etc.)
 // must NOT be marked fully source-covered when those terms are not in
 // the independently verified economic record.
 // XLSX cells are joined with a middle-dot separator: `Total: · $ ...`.
 // Accept only that *leading* separator, never omitted trailing clauses.
 const amountTail=total.slice(totalMatch[0].length).trim()
  .replace(/^·\s*/u,'');
 if(amountTail!==proposal.total_declared)
  return not('uncovered_terms',proposal.lines.length,hash);
 for(let i=0;i<proposal.lines.length;i++){
  const originalLine=lines[i],line=proposal.lines[i];
  if(typeof line.original_description!=='string'||
   line.original_description.length<2||
   !originalLine.toLocaleLowerCase('es-AR').includes(
    line.original_description.toLocaleLowerCase('es-AR')))
    return not('line_not_found',i+1,hash);
  if(!isQuoteLine(line,originalLine))
    return not('field_not_on_source',i+1,hash);
  if(!sourceMoneyCovered(originalLine,line))
    return not('uncovered_money',i+1,hash);
  if(!remainingNumberCovered(originalLine,line))
    return not('uncovered_number',i+1,hash);
  if(unclaimedWords(originalLine,line))
    return not('uncovered_terms',i+1,hash);
 }
 return ok(proposal.lines.length,hash);
}

/**
 * MVP130. Independent, position-aware PDF evidence from the original bytes.
 * PDF.js reads embedded fonts, Flate streams and tables without executing PDF JS.
 * This is NOT an OCR or two-LLM proof; uncertainty always stays private.
 */
import type {DownloadedMedia} from './whapi-media-archive.ts';
import type {DocumentDraft} from './document-ai-draft.ts';
import type {SourceCheckResult} from './supplier-source-text.ts';

export type PageRow=Readonly<{page:number;text:string}>;
export type PdfSourceEvidence=Readonly<{
 rows:readonly PageRow[];
 pages:number;
 scanned:boolean;
}>;
export type EvidenceReader=(bytes:Uint8Array)=>Promise<PdfSourceEvidence>;
type Reason=SourceCheckResult['reason'];
const MONEY=/(?:\$\s*-?\s*\d[\d.,]*|\b\d{1,3}(?:\.\d{3})+(?:,\d{2})?\b|\b\d+,\d{2}\b)/gu;
const PII=/(?:cuit|cuil|whats?app|tel[eé]fono|celular|raz[oó]n social|facturar a|wa\.me|https?:\/\/|@[\w-]+|\b[\w.%+-]+@[\w.-]+\.[a-z]{2,}\b)/iu;
const TERMS=/(?:\biva\b|flete|entrega|formas? de pago|descuento|bonificaci[oó]n|disponib|vencimiento|contado|efectivo|transferencia|precios?\s+(?:de\s+)?lista|\blista\s+\d+\b|devoluci[oó]n|retornabl|pallets?|bolsones?|cr[eé]dito|financiaci[oó]n|impuestos|garant[ií]a)/iu;
const normalized=(s:string)=>s.normalize('NFKC').replace(/\s+/gu,' ').trim().toLocaleLowerCase('es-AR');
const invalid=(f:DownloadedMedia,n:number,r:Reason):SourceCheckResult=>
 Object.freeze({state:'needs_source_review',reason:r,lines:n,
  sourceSha256:f?.sha256??null,sourceVerified:false,
  publicationAllowed:false,rankingAllowed:false});
const covered=(f:DownloadedMedia,n:number):SourceCheckResult=>
 Object.freeze({state:'source_text_covered',reason:'covered',lines:n,
  sourceSha256:f.sha256,sourceVerified:false,
  publicationAllowed:false,rankingAllowed:false});
const mentions=(source:string,term:string|null):boolean=>term===null||
 normalized(source).includes(normalized(term));
// Quantities must be distinct from product size and price digits.
const regexEscape=(value:string):string=>value.replace(/[.*+?^${}()|[\]\\]/gu,'\\$&');
const quantityUnitEvidence=(row:string,description:string,quantity:string|null,unit:string|null):boolean=>{
 const q=normalized(quantity??''),u=normalized(unit??''),desc=normalized(description);
 if(!desc)return false;
 // Cargo, descuento o pallet pueden tener un total sin precio unitario.
 // Nunca deducir "1 unidad". Ambos campos NULL son aceptables SOLAMENTE
 // si no hay un número sin atribuir en la fila fuente original.
 if(quantity===null&&unit===null)return true;
 if(!/^\d+(?:[.,]\d+)?$/u.test(q))return false;
 const at=row.indexOf(desc);
 if(at<0)return false;
 // Strip description with sizes; stop before explicitly marked monetary price.
 let context=row.slice(0,at)+' '+row.slice(at+desc.length);
 const pricedAt=context.search(/\$\s*-?\s*\d/u);
 const moneyStart=pricedAt>=0?pricedAt:context.search(MONEY);
 if(moneyStart>=0)context=context.slice(0,moneyStart);
 if(!u){
  // Without a declared unit, prove a separate numeric quantity cell.
  // An amount or a product size is NOT sufficient evidence.
  if(pricedAt<0)return false;
  const number='(?<![\\p{L}\\p{N}.,])'+regexEscape(q)+'(?![\\p{L}\\p{N}.,])';
  return new RegExp(number,'u').test(context);
 }
 const sep='[\\s|:;·/-]*';
 const pattern='(?<![\\p{L}\\p{N}.,])(?:'+regexEscape(q)+sep+regexEscape(u)+'s?|'+
   regexEscape(u)+'s?'+sep+regexEscape(q)+')(?![\\p{L}\\p{N}.,])';
 return new RegExp(pattern,'iu').test(context);
};

/** Default adapter: pinned PDF.js serverless text extraction. */
export async function readPdfPositioned(bytes:Uint8Array):Promise<PdfSourceEvidence>{
 if(bytes.length<120||bytes.length>8*1024*1024)throw Error('pdf_size_gate');
 const {getDocumentProxy,extractTextItems,inspectPages}=
  await import('npm:unpdf@2.1.0');
 const pdf=await getDocumentProxy(Uint8Array.from(bytes),{
  maxImageSize:16_777_216,isOffscreenCanvasSupported:false,
  isImageDecoderSupported:false
 });
 try{
  if(pdf.numPages<1||pdf.numPages>12)throw Error('pdf_pages_gate');
  const inspection=await inspectPages(pdf);
  if(inspection.totalPages!==pdf.numPages)throw Error('pdf_inspection_gate');
  const scanned=inspection.pages.some(page=>
   page.invisibleTextLength>0||
   page.textLength<20&&page.imageCoverage>0.65);
  if(scanned)return {rows:[],pages:pdf.numPages,scanned:true};
  const extracted=await extractTextItems(pdf);
  if(extracted.totalPages!==pdf.numPages)throw Error('pdf_pages_mismatch');
  let count=0;
  const rows:PageRow[]=[];
  for(const [index,page] of extracted.items.entries()){
   const groups:{y:number;parts:{x:number;text:string}[]}[]=[];
   for(const item of page){
    if(typeof item.str!=='string'||!item.str.trim())continue;
    if(!Number.isFinite(item.x)||!Number.isFinite(item.y))
      throw Error('pdf_geometry_invalid');
    if(++count>9000)throw Error('pdf_too_many_text_items');
    let g=groups.find(v=>Math.abs(v.y-item.y)<=2.0);
    if(!g){g={y:item.y,parts:[]};groups.push(g)}
    g.parts.push({x:item.x,text:item.str});
   }
   for(const group of groups.sort((a,b)=>b.y-a.y)){
    const line=group.parts.sort((a,b)=>a.x-b.x).map(v=>v.text.trim())
     .filter(Boolean).join(' ').replace(/\s+/gu,' ').trim();
    if(line)rows.push({page:index+1,text:line});
    if(rows.length>300)throw Error('pdf_too_many_rows');
   }
  }
  if(!rows.length)throw Error('pdf_no_text');
  return {pages:pdf.numPages,rows,scanned:false};
 }finally{
  // The unpdf proxy type does not expose destroy in every runtime build.
  // Dispose when available; never assume an untyped method exists.
  const disposable=pdf as unknown as {destroy?:()=>Promise<void>|void};
  await disposable.destroy?.();
 }
}

/**
 * Positive result only if every economic figure in every page row was claimed
 * exactly once, along with every commercial condition. We deliberately reject
 * subtotals/ambiguous headers and unmapped numbers instead of guessing.
 */
export async function checkGeneralPdfSource(
 f:DownloadedMedia,p:DocumentDraft,
 reader:EvidenceReader=readPdfPositioned
):Promise<SourceCheckResult>{
 const n=p?.lines?.length??0;
 if(!f||f.mime!=='application/pdf'||!p||p.kind!=='supplier_quote'||n<1||n>25||
    !/^[a-f0-9]{64}$/u.test(f.sha256))
  return invalid(f,n,'invalid_source');
 if(p.unanswered.length||!p.total_declared||p.lines.some(v=>
   v.ambiguity!==null||!v.original_description||
   (v.unit_price!==null&&v.quantity===null)||
   (v.quantity===null&&v.unit!==null)||
   !v.evidence_location.trim()))
  return invalid(f,n,'unresolved');
 for(const line of p.lines){
  if(PII.test(line.original_description)||PII.test(line.unit??'')||
    PII.test(line.ambiguity??''))return invalid(f,n,'unsafe_contact');
 }
 if(PII.test(p.requested_delivery_note??''))return invalid(f,n,'unsafe_contact');
 let source:PdfSourceEvidence;
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{
  source=await Promise.race([
   reader(f.bytes),
   new Promise<never>((_,reject)=>{
    timer=setTimeout(()=>reject(Error('pdf_timeout')),10000);
   })
  ]);
 }catch{return invalid(f,n,'unsupported_layout')}
 finally{if(timer!==undefined)clearTimeout(timer)}
 if(source.scanned||source.pages<1||source.pages>12||
    source.rows.length>300||source.rows.some(v=>v.page<1||v.page>source.pages))
  return invalid(f,n,'unsupported_layout');
 const rows=source.rows.map(v=>normalized(v.text));
 // Each proposed commercial clause must also be visible on the ORIGINAL PDF,
 // not just appear in an AI draft. The PDF source is independent evidence.
 const clauses=(p.requested_delivery_note??'').split(/[;\r\n]+/u)
  .map(v=>normalized(v)).filter(Boolean);
 if(clauses.length>30||clauses.some(v=>!rows.some(row=>row.includes(v))))
  return invalid(f,n,'uncovered_terms');
 const consumed=new Set<number>();
 const money=(v:string)=>Array.from(v.matchAll(MONEY),m=>normalized(m[0]));
 const exactAmounts=(row:string,expected:readonly string[],
  quantity:string|null=null)=>{
  const all=money(row),wanted=expected.flatMap(v=>money(v));
  // Decimal quantity (40,00) is an unprefixed token, NOT a third price.
  // Exclude it only when corroborated before the first explicit $ amount.
  const firstPrice=row.search(/\$\s*-?\s*\d/u);
  if(quantity!==null&&firstPrice>=0&&expected.every(v=>v.includes('$'))){
   const q=normalized(quantity);
   if(new RegExp('(?<![\\p{L}\\p{N}.,])'+regexEscape(q)+
     '(?![\\p{L}\\p{N}.,])','u').test(row.slice(0,firstPrice))){
    const pos=all.indexOf(q);
    if(pos>=0)all.splice(pos,1);
   }
  }
  return all.length===wanted.length&&wanted.every(v=>{
   const i=all.indexOf(v);if(i<0)return false;all.splice(i,1);return true;
  });
 };
 for(const line of p.lines){
  const idx=rows.findIndex((row,i)=>!consumed.has(i)&&
   mentions(row,line.original_description)&&
   quantityUnitEvidence(row,line.original_description,line.quantity,line.unit)&&
   mentions(row,line.unit_price)&&mentions(row,line.line_total));
  if(idx<0)return invalid(f,n,'line_not_found');
  const declared=[line.unit_price,line.line_total]
    .filter((v):v is string=>typeof v==='string'&&v.length>0);
  if(!exactAmounts(rows[idx],declared,line.quantity))
   return invalid(f,n,'uncovered_money');
  // Sin cantidad/unidad, ninguna cifra puede ser inventada o perderse.
  // Después de retirar literalmente descripción y TODOS los importes,
  // un porcentaje/desplazamiento/importe sin citar obliga a revisión.
  if(line.quantity===null&&line.unit===null){
   const at=rows[idx].indexOf(normalized(line.original_description));
   if(at<0)return invalid(f,n,'line_not_found');
   const raw=(rows[idx].slice(0,at)+' '+
     rows[idx].slice(at+normalized(line.original_description).length))
     .replace(MONEY,' ');
   MONEY.lastIndex=0;
   if(/\d/u.test(raw))return invalid(f,n,'uncovered_number');
  }
  const economicTerm=rows[idx].match(TERMS)?.[0]??null;
  if(economicTerm&&
    !mentions(line.original_description,economicTerm)&&
    !mentions(p.requested_delivery_note??'',economicTerm))
   return invalid(f,n,'uncovered_terms');
  consumed.add(idx);
 }
 const totalCandidates=rows.map((text,index)=>({text,index})).filter(v=>
  !consumed.has(v.index)&&/\b(?:total(?:\s+general)?|importe\s+total|a\s+pagar)\b/iu.test(v.text)
  &&mentions(v.text,p.total_declared));
 if(totalCandidates.length!==1)return invalid(f,n,'total_not_found');
 if(!exactAmounts(totalCandidates[0].text,[p.total_declared]))
  return invalid(f,n,'uncovered_money');
 consumed.add(totalCandidates[0].index);
 for(const [i,row] of rows.entries()){
  // No money may be ignored: all amount-bearing rows must map to an
  // original supplier line (including freight, pallets and discounts) or total.
  if(!consumed.has(i)&&MONEY.test(row)){
   MONEY.lastIndex=0;
   return invalid(f,n,'uncovered_money');
  }
  MONEY.lastIndex=0;
  // Only full exact source terms copied into the supplier's note can claim
  // numbers such as LISTA 7. A money-bearing row is never hidden as a note.
  const noteClaim=!consumed.has(i)&&TERMS.test(row)&&
   normalized(p.requested_delivery_note??'').includes(row);
  if(!consumed.has(i)&&TERMS.test(row)&&!noteClaim)
   return invalid(f,n,'uncovered_terms');
  if(!consumed.has(i)&&/\d/u.test(row)&&!noteClaim)
   return invalid(f,n,'uncovered_number');
 }
 return covered(f,n);
}

/**
 * MVP251 — diagnóstico de originales visuales de presupuestos (JPEG/PNG/WebP).
 * Dos lecturas de visión concordantes NO son una prueba independiente del píxel:
 * la fuente sigue PRIVADA y requiere una corroboración ajena al LLM o revisión.
 * Esta función no guarda datos, no publica, no clasifica competitividad ni envía.
 */
import type {DocumentDraft} from './document-ai-draft.ts';
import type {DownloadedMedia} from './whapi-media-archive.ts';
import type {SourceCheckResult} from './supplier-source-text.ts';

type Reason=SourceCheckResult['reason'];
const MIME=new Set(['image/jpeg','image/png','image/webp']);
const SHA=/^[a-f0-9]{64}$/u;
const PII=/(?:\bcuit\b|\bcuil\b|whats?app|celular|tel[eé]fono|raz[oó]n social|direcci[oó]n|contacto|https?:\/\/|wa\.me|@[\w.-]+|[\w.%+-]+@[\w.-]+\.[a-z]{2,}|\+54[\s-]*\d)/iu;
const control=/[\u0000-\u001f\u007f]/u;

const result=(source:DownloadedMedia|null,reason:Reason,lines:number):SourceCheckResult=>
 Object.freeze({state:'needs_source_review',reason,lines,
  sourceSha256:SHA.test(source?.sha256??'')?source!.sha256:null,
  sourceVerified:false,publicationAllowed:false,rankingAllowed:false});

function signature(bytes:Uint8Array,mime:string):boolean{
 const start=(...arr:number[])=>arr.every((v,i)=>bytes[i]===v);
 if(mime==='image/jpeg')return start(0xff,0xd8,0xff);
 if(mime==='image/png')return start(0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a);
 if(mime==='image/webp')return start(0x52,0x49,0x46,0x46)&&
   bytes.length>=12&&startAt(bytes,8,0x57,0x45,0x42,0x50);
 return false;
}
function startAt(bytes:Uint8Array,offset:number,...values:number[]):boolean{
 return values.every((v,i)=>bytes[offset+i]===v);
}
function validReading(read:DocumentDraft|null):read is DocumentDraft{
 if(!read||read.status!=='review_required'||
    read.kind!=='supplier_quote'||!Array.isArray(read.lines)||
    read.lines.length<1||read.lines.length>25||
    !Array.isArray(read.unanswered)||read.unanswered.length>0||
    typeof read.total_declared!=='string'||!read.total_declared.trim()||
    !read.lines.every(line=>line&&line.ambiguity===null&&
      typeof line.original_description==='string'&&
      line.original_description.trim().length>=2&&
      typeof line.evidence_location==='string'&&
      line.evidence_location.trim().length>0&&
      [line.quantity,line.unit,line.unit_price,line.line_total].every(
        v=>v===null||typeof v==='string'&&v.length<=256
      )))return false;
 return true;
}
function claimedPII(read:DocumentDraft):boolean{
 const fields=[
  read.total_declared,read.requested_delivery_note,read.delivery_city,
  ...read.unanswered,
  ...read.lines.flatMap(line=>[
   line.original_description,line.quantity,line.unit,
   line.unit_price,line.line_total,line.evidence_location
  ])
 ];
 return fields.some(v=>typeof v==='string'&&(PII.test(v)||control.test(v)));
}
function signatureOfReading(read:DocumentDraft):string{
 // Misma representación económica, sin interpretar ni normalizar cifras.
 // La ubicación puede variar entre dos lecturas independientes, pero las
 // celdas, cantidades, precios, descripción y notas deben coincidir.
 return JSON.stringify({
  kind:read.kind,total:read.total_declared,
  delivery_city:read.delivery_city,
  note:read.requested_delivery_note,
  lines:read.lines.map(line=>[
   line.original_description,line.quantity,line.unit,
   line.unit_price,line.line_total
  ])
 });
}

/** Requisito independiente del motor OCR: sin dos lecturas, no cotejar. */
export function lecturasVisualesConcordantesMvp252(
 first:DocumentDraft|null,second:DocumentDraft|null
):boolean{
 return validReading(first)&&validReading(second)&&
  !claimedPII(first)&&!claimedPII(second)&&
  signatureOfReading(first)===signatureOfReading(second);
}

/** SIEMPRE retorna needs_source_review. Nunca autoriza publicación visual. */
export async function checkSupplierImageSourceMvp251(
 source:DownloadedMedia,
 first:DocumentDraft|null,
 second:DocumentDraft|null
):Promise<SourceCheckResult>{
 const count=Array.isArray(first?.lines)?first.lines.length:0;
 if(!source||!MIME.has(source.mime))return result(source,'unsupported_format',count);
 if(!(source.bytes instanceof Uint8Array)||source.bytes.length<12||
    source.bytes.length>8*1024*1024||!SHA.test(source.sha256)||
    !signature(source.bytes,source.mime))
  return result(source,'invalid_source',count);
 const hashed=Array.from(
  new Uint8Array(await crypto.subtle.digest('SHA-256',Uint8Array.from(source.bytes))),
  b=>b.toString(16).padStart(2,'0')
 ).join('');
 if(hashed!==source.sha256)return result(source,'invalid_source',count);
 // No se aceptan fuentes con remitente/identidad incluida en los campos
