import {
 interpretarPresupuestoConIAMvp225,
 type LecturaOfertaMvp225
} from '../../../src/domain/ia-central/lector-presupuesto-proveedor-mvp225.ts';
import {
 RUBROS_MVP216,type RubroMvp216
} from '../../../src/domain/rubros-comprador-mvp216.ts';
