  summary:Record<string,unknown>|null)=>{
  const r=await db('cotironda_piloto_ia_finish_quote_mvp227',{
   p_message_hmac:args.messageHmac,p_chat_hmac:args.chatHmac,
   p_state:state,p_reason:reason,p_summary:summary
  });
